<?php
namespace App\Http\Controllers; use App\Models\WasteCategory; use App\Http\Requests\{StoreWasteCategoryRequest,UpdateWasteCategoryRequest}; use Illuminate\Http\Request;
class WasteCategoryController extends Controller {public function index(Request $r){$q=WasteCategory::query()->when($r->search,fn($x,$s)=>$x->where('name','like',"%$s%"));$cats=$q->orderBy($r->get('sort','name'),$r->get('dir','asc')==='desc'?'desc':'asc')->paginate(10)->withQueryString();return view('categories.index',compact('cats'));} public function create(){return view('categories.form',['category'=>new WasteCategory]);} public function store(StoreWasteCategoryRequest $r){WasteCategory::create($r->validated());return redirect()->route('categories.index')->with('success','Kategori berhasil ditambahkan.');} public function edit(WasteCategory $category){return view('categories.form',compact('category'));} public function update(UpdateWasteCategoryRequest $r,WasteCategory $category){$category->update($r->validated());return redirect()->route('categories.index')->with('success','Kategori berhasil diubah.');} public function destroy(WasteCategory $category){$category->delete();return back()->with('success','Kategori dihapus (soft delete).');}}
